export function makeDiamond(character: string): string {
  const charCode = character.charCodeAt(0);
  const size = charCode - 65 + 1;
  let result = '';

  for (let i = 0; i < size; i++) {
    const currentChar = String.fromCharCode(65 + i);
    const spaces = ' '.repeat(size - i - 1);
    const middleSpaces = i > 0 ? ' '.repeat(2 * i - 1) : '';
    result += `${spaces}${currentChar}${middleSpaces}${currentChar}${spaces}\n`;
  }

  for (let i = size - 2; i >= 0; i--) {
    const currentChar = String.fromCharCode(65 + i);
    const spaces = ' '.repeat(size - i - 1);
    const middleSpaces = ' '.repeat(2 * i - 1);
    result += `${spaces}${currentChar}${middleSpaces}${currentChar}${spaces}\n`;
  }

  return result;
}
